"""Conservative index evidence candidate; no supplier-cost or personality inference.

Only series referenced by the case or its parts' cost-driver records are eligible. Exact calendar-year
windows avoid treating thirteen sparse observations as twelve months.
"""

import math
import re
from dataclasses import dataclass

INDEX_ID = re.compile(r"idx:([A-Za-z0-9_-]+)@(\d{4}-\d{2})\Z")


def _month(value):
    if not isinstance(value, str) or not re.fullmatch(r"\d{4}-\d{2}", value):
        return None
    year, month = map(int, value.split("-"))
    return year * 12 + month - 1 if 1 <= month <= 12 else None


def _index(ref, fact):
    match = INDEX_ID.fullmatch(ref)
    if not match or not isinstance(fact, dict):
        return None
    series, month = match.groups()
    value = fact.get("value")
    if (fact.get("series") != series or fact.get("month") != month or _month(month) is None
            or isinstance(value, bool) or not isinstance(value, (int, float))
            or not math.isfinite(value) or value <= 0):
        return None
    return series, month, float(value)


@dataclass(frozen=True)
class IndexClaim:
    refs: tuple[str, str]
    change_pct: float

    def sentence(self, facts):
        """Recompute before rendering; reject a changed or unsupported assertion."""
        rows = [_index(ref, facts.get(ref)) for ref in self.refs]
        if any(row is None for row in rows):
            raise ValueError("unknown or malformed index fact")
        (series, start, before), (other, end, after) = rows
        change = (after / before - 1) * 100
        if (series != other or _month(end) - _month(start) != 12
                or not math.isfinite(self.change_pct)
                or not math.isclose(change, self.change_pct, abs_tol=1e-9)):
            raise ValueError("unsupported index assertion")
        return (f"The {series} index changed {change:+.2f}% from {start} to {end} "
                f"({self.refs[0]}, {self.refs[1]}).")


def cost_driver_series(package):
    """Base-package part/series links; weights are not external cost assertions."""
    if package.db is None:
        return {}
    links = {}
    for row in package.query("SELECT DISTINCT part_id, series_id FROM cost_drivers", limit=100000):
        links.setdefault(row["part_id"], set()).add(row["series_id"])
    return links


def index_claims(case, facts, series_by_part=None):
    """One recent year-on-year observation per case-referenced series, lowest first."""
    if case.get("type") != "price_increase":
        return []
    allowed = {m.group(1) for ref in case.get("refs", []) if (m := INDEX_ID.fullmatch(ref))}
    for part in case.get("parts", []):
        allowed.update((series_by_part or {}).get(part, ()))
    rows = {ref: row for ref, fact in facts.items() if (row := _index(ref, fact))}
    if not rows:
        return []
    latest = max(_month(row[1]) for row in rows.values())
    claims = []
    for series in sorted(allowed):
        candidates = sorted(((ref, row) for ref, row in rows.items() if row[0] == series),
                            key=lambda item: item[1][1], reverse=True)
        if not candidates:
            continue
        end_ref, (_, end, after) = candidates[0]
        start = f"{int(end[:4]) - 1:04d}{end[4:]}"
        start_ref = f"idx:{series}@{start}"
        if start_ref not in rows or latest - _month(end) > 12:
            continue
        change = (after / rows[start_ref][2] - 1) * 100
        if math.isfinite(change):
            claims.append(IndexClaim((start_ref, end_ref), change))
    return sorted(claims, key=lambda claim: (claim.change_pct, claim.refs))


def supplier_rejects_indices(events):
    """Conservative textual veto, not a claim about hidden supplier economics.

    Only supplier prose is inspected. A prior rejection keeps the index path off
    for this thread; no attempt is made to infer when a hedge expires.
    """
    for message in events:
        if message.get("from") == "buyer":
            continue
        body = (message.get("body") or "").lower()
        if re.search(r"\b(?:hedged|hedging|bought forward|fixed energy contract)\b", body):
            return True
        if re.search(r"\b(?:index|indices|market data)\b[^.!?\n]{0,100}"
                     r"(?:not relevant|irrelevant|do not reflect|does not reflect|not our costs)", body):
            return True
        if any(c.get("result") == "contradicted" for c in message.get("claim_results") or []):
            return True
    return False


def evidence_for_offer(case, package_facts, threads, limit=2, series_by_part=None, supplier_id=None):
    """Select unused citations across the case from confirmed buyer history.

    Repeated decisions on unchanged history produce the same message. Actual retry
    persistence and concurrent reservation remain the runtime's responsibility.
    """
    facts = {**package_facts, **(case.get("facts") or {})}
    if supplier_id is not None:
        events = threads.get(supplier_id, [])
        replies = [m for m in events if m.get("from") != "buyer"]
        if replies and replies[-1].get("status") in {"final_offer", "agreed", "walked_away", "no_bid"}:
            return []
        if supplier_rejects_indices(events):
            return []
    used = set()
    for events in threads.values():
        for message in events:
            if message.get("from") != "buyer":
                continue
            used.update(message.get("refs") or [])
            used.update(m.group(0) for m in re.finditer(
                r"idx:[A-Za-z0-9_-]+@\d{4}-\d{2}", message.get("body") or ""))
    selected = []
    for claim in index_claims(case, facts, series_by_part):
        # A positive input-price change supports the supplier unless we have a
        # verified cost decomposition. This candidate has no such decomposition.
        if claim.change_pct > 0:
            continue
        if used.intersection(claim.refs):
            continue
        if len(selected) >= min(2, max(0, limit)):
            break
        selected.append((claim, claim.sentence(facts)))
        used.update(claim.refs)
    return selected


def pick(bank: list[Claim], used_ids: set[str], max_claims: int = MAX_CHECKED, *,
         supplier_id: str | None = None, case_type: str | None = None, allow_adverse: bool = False,
         disclosures: frozenset[str] | set[str] = DEFAULT_DISCLOSURE,
         skip_kinds: frozenset[str] | set[str] = frozenset(), allow_cherry_pick: bool = False,
         index_priorities: dict[str, int] | None = None) -> list[Claim]:
    """At most `max_claims` (never more than 3) unused claims for `supplier_id`.

    Defaults: only claims that support the buyer, latest index windows only, disclosing nothing private (pass
    `disclosures | {"reveals_rival"}` to cite a rival quote deliberately). Order by case type,
    then optional index relevance, case refs and strength. Callers add `claim_keys(c)` of sent claims to `used_ids`."""
    order = KIND_ORDER.get(case_type or "", DEFAULT_ORDER)
    rank = {k: i for i, k in enumerate(order)}
    cands = [c for c in bank
             if (allow_adverse or c.supports_buyer) and c.disclosure in disclosures and c.kind not in skip_kinds
             and (allow_cherry_pick or not c.cherry_picked)
             and (supplier_id is None or c.supplier_id in (None, supplier_id))]
    cands.sort(key=lambda c: (not c.supports_buyer, rank.get(c.kind, len(rank)),
                              (index_priorities or {}).get(c.subject, 0) if c.kind == "index_change" else 0,
                              not c.in_case_refs, -c.strength))
    out, taken, subjects = [], set(used_ids), set()
    for c in cands:
        if len(out) >= min(max_claims, MAX_CHECKED):
            break
        keys = claim_keys(c)
        raw = set(c.ids)
        if keys & taken or (c.disclosure != "reveals_rival" and raw & taken) or (c.kind, c.subject) in subjects:
            continue
        out.append(c)
        taken |= keys | raw
        subjects.add((c.kind, c.subject))
    return out


def index_relevance(bank, case, package=None, events=()):
    """Rank only known series mentions; supplier prose cannot authorize claims or disclosure."""
    series = {c.subject for c in bank if c.kind == "index_change" and c.subject}
    cited = {r[4:].split("@")[0] for r in case.get("refs", []) if r.startswith("idx:")}
    latest = next((e for e in reversed(events) if e.get("from") != "buyer" and e.get("body")), {})
    text = latest.get("body", "")
    mentioned = {sid for sid in series if isinstance(text, str)
                 and re.search(rf"(?<![\w-]){re.escape(sid)}(?![\w-])", text)}
    trigger = ""
    ref = case.get("trigger_doc")
    if package is not None and ref:
        row = case_facts(case, package).get(ref, {})
        if row.get("supplier") in case.get("suppliers", []):
            try:
                trigger = package.document(ref)
            except (OSError, ValueError, AttributeError):
                pass
    stated = {sid for sid in series if re.search(rf"(?<![\w-]){re.escape(sid)}(?![\w-])", trigger)}
    reasons = {}
    priorities = {}
    for sid in sorted(series):
        if sid in mentioned:
            priority, reason = 0, "latest supplier message names series"
        elif sid in stated or sid in cited:
            priority, reason = 1, "trigger document or case reference names series"
        elif any(c.subject == sid and c.driver_weight is not None for c in bank):
            priority, reason = 2, "listed part cost driver"
        else:
            priority, reason = 3, "no explicit explanation or driver link"
        priorities[sid], reasons[sid] = priority, reason
    return priorities, reasons
    def enrich(self, case, threads, sid, move, context=None, rfq_claims=0):
        """`rfq_claims` > 0 enables RFQ (multi-supplier) decoration with at most that many claims,
        excluding our internal should-cost; the single-supplier gate stays for every other path."""
        message = move.get("message")
        rfq = rfq_claims > 0 and case.get("type") == "rfq"
        if rfq:
            if not message or not message.get("term_sheets") or message.get("action"):
                return move
        elif not self.eligible(case, move):
            return move
        cid = case["case_id"]
        try:
            context = context if context is not None else self.context_for(case)
            if (
                context.case_id != cid
                or context.supplier_ids != tuple(case.get("suppliers") or [])
                or context.part_ids != tuple(case.get("parts") or [])
            ):
                raise ValueError("context scope mismatch")
            facts = case_facts(case, self.package)
            used = set(self.reserved.get(cid, set()))
            for events in threads.values():
                for event in events:
                    if event.get("from") == "buyer":
                        used.update(event.get("refs") or [])
            existing = set(message.get("refs") or [])
            used.update(existing)
            bank = [c for c in context.candidates if verify(c, facts, self.package, case)]
            priorities, reasons = index_relevance(bank, case, self.package, threads.get(sid, []))
            # Each pre-existing ref conservatively consumes one checked-claim slot.
            budget = max(0, MAX_CHECKED - len(existing))
            if rfq:
                budget = min(budget, rfq_claims)
            chosen = pick(
                bank, used, max_claims=budget, supplier_id=sid,
                case_type="renewal_trade" if case["type"] == "renewal" else case["type"],
                index_priorities=priorities,
                skip_kinds=frozenset({"should_cost"}) if rfq else frozenset(),
            )
        except DATA_ERRORS as exc:
            self.fallback(case, exc)
            return move
        if self.tracer:
